import sys
import math

def compute_hcf(a, b, c):
    return math.gcd(math.gcd(a, b), c)

def main():
    n = int(sys.stdin.readline().strip())
    if n < 6:
        print(0)
        return
    for a in range(2, n // 3 + 2):
        for b in range(a, (n - a) // 2 + 1):
            c = n - a - b
            if c < b:
                continue
            g = compute_hcf(a, b, c)
            if g == 1:
                print(f"{a} {b} {c}")
                return
    print(0)

if __name__ == "__main__":
    main()
